declare global {interface Window {referenceOperation?:{action:string;body:unknown};fixtureCommand:(action:string,body:Record<string,unknown>)=>unknown}}
window.fixtureCommand=(action,body)=>{
 if(action==='count_workspace')return {rows:counts,openCount:2};
 if(action==='sales_analytics'){
  const filters=body as SalesFilters,asOf=new Date().toISOString(),dates=analyticsDates(filters,asOf),days=Math.round((Date.parse(dates.throughDate)-Date.parse(dates.fromDate))/86400000)+1;
  const trend=Array.from({length:days},(_,n)=>{const date=new Date(Date.parse(dates.fromDate)+n*86400000).toISOString().slice(0,10),gross=String((n+1)*125000);return {date,throughDate:date,grossSales:gross,salesCount:n+1,refunds:'0',recoveries:'0',netCash:gross};});const count=trend.reduce((n,p)=>n+p.salesCount,0),gross=String(count*125000);
  return {version:1,branchId:'test',period:filters.period,interval:filters.interval,...dates,days,asOf,lastSync:asOf,totals:{grossSales:gross,salesCount:count,refunds:'0',recoveries:'0',netCash:gross,averageSale:'125000'},previous:{grossSales:'0',salesCount:0,refunds:'0',recoveries:'0',netCash:'0',averageSale:'0'},trend,products:[{id:'seed',name:products[0].name,sku:products[0].sku,base_unit:'piece',quantity:String(count),grossSales:gross,purchases:count,previousPurchases:0}]};
 }throw Error('Unexpected fixture request');
};
